// Separate read-only post-application audit; does not use the writer's verification code.
import fs from 'node:fs';import crypto from 'node:crypto';import assert from 'node:assert/strict';import {createRequire} from 'node:module';import {isDeepStrictEqual as equal} from 'node:util';
const root=process.cwd(),dir='docs/audits/jpn_dp4_official_artist84_20261120',require=createRequire(`${root}/backend/package.json`),cfg=require('dotenv').parse(fs.readFileSync(`${root}/.env.local`)),ref='ycdxbpibncqcchqiihfz',u=new URL(cfg.SUPABASE_DB_URL),sha=b=>crypto.createHash('sha256').update(b).digest('hex'),pin='c0a2628c37701c1a9cbba942fca639f62cf8c99640889c7067e8f96bf8a785ab';assert.equal(new URL(cfg.SUPABASE_URL).hostname,`${ref}.supabase.co`);assert.ok(`${u.hostname} ${decodeURIComponent(u.username)}`.includes(ref));assert.match(fs.readFileSync('supabase/config.toml','utf8'),new RegExp(`project_id\\s*=\\s*"${ref}"`));const bytes=fs.readFileSync(`${dir}/artist84-plan-v2-20261120.json`);assert.equal(sha(bytes),pin);const plan=JSON.parse(bytes);assert.equal(plan.rows.length,84);const ids=plan.rows.map(r=>r.parent_before.id),{Client}=require('pg'),db=new Client({connectionString:cfg.SUPABASE_DB_URL,connectionTimeoutMillis:10000});await db.connect();try{await db.query('begin isolation level repeatable read read only');await db.query("set local statement_timeout='60s'");const sanity=(await db.query("select current_setting('transaction_read_only') read_only,(select count(*)::int from public.card_prints) parents,(select count(*)::int from public.sets) sets")).rows[0];assert.equal(sanity.read_only,'on');assert.ok(sanity.parents>=40000&&sanity.sets>=150);const q=async(sql,args)=>(await db.query(sql,args)).rows,parents=(await q('select to_jsonb(p) row from public.card_prints p where id=any($1::uuid[])',[ids])).map(x=>x.row),identities=(await q('select to_jsonb(i) row from public.card_print_identity i where card_print_id=any($1::uuid[])',[ids])).map(x=>x.row),links=(await q('select to_jsonb(l) row from public.card_print_species l where card_print_id=any($1::uuid[])',[ids])).map(x=>x.row),receipts=await q(`select id::text,payload from public.raw_imports where source=$1 and payload->>'package_fingerprint'=$2 and payload->>'_kind'='dp4_artist84_receipt' order by id`,['grookai_jpn_dp4_artist84_v1',pin]);assert.equal(parents.length,84);assert.equal(receipts.length,7);const pidx=new Map(parents.map(x=>[x.id,x])),sort=a=>[...a].sort((a,b)=>String(a.id).localeCompare(String(b.id)));for(let chunk=0;chunk<7;chunk++){const part=plan.rows.slice(chunk*12,chunk*12+12),matching=receipts.filter(x=>x.payload.chunk===chunk);assert.equal(matching.length,1);const receipt=matching[0],raw=(await q('select payload from public.raw_imports where id=$1 and source=$2',[receipt.payload.source_snapshot_raw_import_id,'grookai_jpn_dp4_artist84_v1']))[0]?.payload;assert.ok(raw);assert.equal(raw._kind,'dp4_artist84_source_snapshot');assert.equal(raw.package_fingerprint,pin);assert.equal(raw.chunk,chunk);assert.equal(raw.run_id,receipt.payload.run_id);assert.equal(raw.writer_fingerprint,receipt.payload.writer_fingerprint);assert.ok(equal(raw.rows,part));assert.equal(sha(Buffer.from(raw.plan_base64,'base64')),pin);assert.equal(raw.sources.length,12);for(const r of part){assert.ok(equal(pidx.get(r.parent_before.id),{...r.parent_before,artist:r.source.artist}));assert.ok(equal(sort(identities.filter(x=>x.card_print_id===r.parent_before.id)),sort(r.identities_before)));assert.ok(equal(sort(links.filter(x=>x.card_print_id===r.parent_before.id)),sort(r.links_before)));const s=raw.sources.find(x=>x.official_id===r.source.official_id);assert.ok(s);assert.equal(s.page_url,r.source.official_page);assert.equal(s.image_url,r.source.official_image);assert.equal(sha(Buffer.from(s.page_base64,'base64')),r.source.official_page_sha256);assert.equal(sha(Buffer.from(s.image_base64,'base64')),r.source.image_sha256);}}
await db.query('rollback');const out={version:'DP4_ARTIST84_INDEPENDENT_READBACK_V1',verified_at:new Date().toISOString(),status:'passed',scope:'Separate read-only snapshot checks 84 exact parent postimages, all identity and link preimages, and seven retained source/receipt packages.',sanity,records:84,chunks:7,receipt_ids:receipts.map(x=>x.id)};fs.writeFileSync(`${dir}/independent-artist84-readback-20261120.json`,JSON.stringify(out,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify(out));}finally{await db.end()}
